PRAGMA foreign_keys = ON;

-- 誰が何で動いたかだけ（状態は持たない ・ 書き換えない）。親は SAS が初めて見たとき、子は起動したときに1行
CREATE TABLE sessions (
  id          TEXT PRIMARY KEY,                       -- ツールのセッション ID（親は --session か環境変数、子はツールの出力の session_id）
  role        TEXT NOT NULL CHECK (role IN ('caller','writer','checker')),
  parent_id   TEXT REFERENCES sessions(id),           -- 子を起動させた親。親の行と、人が起動させた子は NULL
  tool        TEXT NOT NULL,                          -- claude-code ・ codex など（接続の定義の名前）
  model       TEXT,                                   -- 子を起動したモデル。親は分からなければ NULL
  launch      TEXT CHECK (launch IS NULL OR json_valid(launch)),  -- 子の起動の設定。--continue で同じものを渡す
  first_seen  TEXT NOT NULL,                          -- ISO 8601 UTC
  CHECK (role <> 'caller' OR (parent_id IS NULL AND launch IS NULL)),
  CHECK (role = 'caller' OR launch IS NOT NULL)
) STRICT;
CREATE INDEX sessions_by_parent ON sessions (parent_id, role) WHERE parent_id IS NOT NULL;
CREATE TRIGGER sessions_no_update BEFORE UPDATE ON sessions BEGIN SELECT RAISE(ABORT, 'sessions are append-only'); END;
CREATE TRIGGER sessions_no_delete BEFORE DELETE ON sessions BEGIN SELECT RAISE(ABORT, 'sessions are append-only'); END;
CREATE TRIGGER sessions_parent_is_caller BEFORE INSERT ON sessions
WHEN NEW.parent_id IS NOT NULL AND (SELECT role FROM sessions WHERE id = NEW.parent_id) IS NOT 'caller'
BEGIN SELECT RAISE(ABORT, 'the parent must be a caller session'); END;

-- 書いた変更（作成 ・ 更新 ・ 削除）。断った操作は持たない（理由はその場で返す）
CREATE TABLE changes (
  id                 TEXT PRIMARY KEY,
  at                 TEXT NOT NULL,
  kind               TEXT NOT NULL CHECK (kind IN ('create','update','delete')),
  target_path        TEXT NOT NULL,
  before_hash        TEXT,                              -- 作成は無い
  after_hash         TEXT,                              -- 削除は無い
  intent             TEXT,
  request_id         TEXT,
  source             TEXT NOT NULL DEFAULT 'sas' CHECK (source IN ('sas','outside')),
  cause_id           TEXT REFERENCES changes(id),       -- 原因の削除（参照元の書き換え）
  parent_session_id  TEXT REFERENCES sessions(id),      -- 呼んだ親。人は NULL
  child_session_id   TEXT REFERENCES sessions(id),      -- 書いた書く子。機械だけなら NULL
  CHECK ((kind = 'create') = (before_hash IS NULL)),
  CHECK ((kind = 'delete') = (after_hash IS NULL)),
  CHECK (kind <> 'delete' OR intent IS NOT NULL),
  CHECK (source = 'sas' OR kind <> 'delete'),
  CHECK (source = 'sas' OR kind <> 'update' OR intent IS NOT NULL),
  CHECK (cause_id IS NULL OR request_id IS NULL)
) STRICT;
CREATE UNIQUE INDEX changes_one_per_request ON changes (request_id) WHERE request_id IS NOT NULL;
CREATE INDEX changes_by_target ON changes (target_path, at);
CREATE INDEX changes_by_parent ON changes (parent_session_id, at) WHERE parent_session_id IS NOT NULL;

CREATE TABLE field_changes (
  change_id           TEXT NOT NULL REFERENCES changes(id),
  pointer             TEXT NOT NULL,                     -- JSON ポインタ
  change              TEXT NOT NULL CHECK (change IN ('add','remove','replace')),
  before              TEXT CHECK (before IS NULL OR json_valid(before)),
  after               TEXT CHECK (after IS NULL OR json_valid(after)),
  before_unavailable  INTEGER NOT NULL DEFAULT 0 CHECK (before_unavailable IN (0,1)),
  PRIMARY KEY (change_id, pointer),
  CHECK (change IS NOT 'add'    OR before IS NULL),
  CHECK (change IS NOT 'remove' OR after IS NULL),
  CHECK (before_unavailable = 0 OR before IS NULL)
) STRICT;

-- 検証。対象を変えないので指紋は1つ。依頼の ID ・ 意図を持たない
CREATE TABLE validations (
  id                 TEXT PRIMARY KEY,
  at                 TEXT NOT NULL,
  target_path        TEXT NOT NULL,
  hash               TEXT NOT NULL,
  parent_session_id  TEXT REFERENCES sessions(id),
  child_session_id   TEXT REFERENCES sessions(id)      -- 判定した確かめる子。機械と人の rule だけなら NULL
) STRICT;
CREATE INDEX validations_by_target ON validations (target_path, at);

CREATE TABLE rule_results (
  validation_id  TEXT NOT NULL REFERENCES validations(id),
  rule_schema    TEXT NOT NULL,                           -- rule を持つスキーマの URN
  rule_id        TEXT NOT NULL,
  pointer        TEXT NOT NULL,
  by             TEXT NOT NULL CHECK (by IN ('machine','ai','human')),
  result         TEXT NOT NULL CHECK (result IN ('verified','violated','unverified','unsupported','error')),
  reason         TEXT,
  grounds        TEXT CHECK (grounds IS NULL OR json_valid(grounds)),
  reads_hash     TEXT NOT NULL,
  details        TEXT CHECK (details IS NULL OR json_valid(details)),
  PRIMARY KEY (validation_id, rule_schema, rule_id, pointer),
  CHECK (by IS NOT 'human' OR result = 'unverified')
) STRICT;

-- 子の役割は表で決まる ・ 原因は削除だけ ・ 親の欄は親の行だけ
CREATE TRIGGER changes_child_is_writer BEFORE INSERT ON changes
WHEN NEW.child_session_id IS NOT NULL AND (SELECT role FROM sessions WHERE id = NEW.child_session_id) IS NOT 'writer'
BEGIN SELECT RAISE(ABORT, 'a change is made by a writer'); END;
CREATE TRIGGER validations_child_is_checker BEFORE INSERT ON validations
WHEN NEW.child_session_id IS NOT NULL AND (SELECT role FROM sessions WHERE id = NEW.child_session_id) IS NOT 'checker'
BEGIN SELECT RAISE(ABORT, 'a validation is made by a checker'); END;
CREATE TRIGGER changes_parent_is_caller BEFORE INSERT ON changes
WHEN NEW.parent_session_id IS NOT NULL AND (SELECT role FROM sessions WHERE id = NEW.parent_session_id) IS NOT 'caller'
BEGIN SELECT RAISE(ABORT, 'parent_session_id must point to a caller session'); END;
CREATE TRIGGER validations_parent_is_caller BEFORE INSERT ON validations
WHEN NEW.parent_session_id IS NOT NULL AND (SELECT role FROM sessions WHERE id = NEW.parent_session_id) IS NOT 'caller'
BEGIN SELECT RAISE(ABORT, 'parent_session_id must point to a caller session'); END;
CREATE TRIGGER changes_cause_is_delete BEFORE INSERT ON changes
WHEN NEW.cause_id IS NOT NULL
  AND (NEW.kind IS NOT 'update' OR NEW.source IS NOT 'sas' OR (SELECT kind FROM changes WHERE id = NEW.cause_id) IS NOT 'delete')
BEGIN SELECT RAISE(ABORT, 'a cause must be a delete'); END;
-- 追記だけ（4表とも）
CREATE TRIGGER changes_no_update BEFORE UPDATE ON changes BEGIN SELECT RAISE(ABORT, 'changes are append-only'); END;
CREATE TRIGGER changes_no_delete BEFORE DELETE ON changes BEGIN SELECT RAISE(ABORT, 'changes are append-only'); END;
CREATE TRIGGER field_changes_no_update BEFORE UPDATE ON field_changes BEGIN SELECT RAISE(ABORT, 'field changes are append-only'); END;
CREATE TRIGGER field_changes_no_delete BEFORE DELETE ON field_changes BEGIN SELECT RAISE(ABORT, 'field changes are append-only'); END;
CREATE TRIGGER validations_no_update BEFORE UPDATE ON validations BEGIN SELECT RAISE(ABORT, 'validations are append-only'); END;
CREATE TRIGGER validations_no_delete BEFORE DELETE ON validations BEGIN SELECT RAISE(ABORT, 'validations are append-only'); END;
CREATE TRIGGER rule_results_no_update BEFORE UPDATE ON rule_results BEGIN SELECT RAISE(ABORT, 'rule results are append-only'); END;
CREATE TRIGGER rule_results_no_delete BEFORE DELETE ON rule_results BEGIN SELECT RAISE(ABORT, 'rule results are append-only'); END;

-- UC7「操作の記録を読む」：変更と検証を時刻順に並べる
CREATE VIEW operations AS
  SELECT id, at, kind, target_path, before_hash, after_hash, intent, request_id, source, cause_id, parent_session_id, child_session_id FROM changes
  UNION ALL
  SELECT id, at, 'validate', target_path, hash, hash, NULL, NULL, 'sas', NULL, parent_session_id, child_session_id FROM validations;
